def _sanitize_filename(name):
    invalid = r'\/:*?"<>|'
    for ch in invalid:
        name = name.replace(ch, "_")
    return name


def export_to_STL(zobj, force="STL"):

    exportPath = bpy.context.scene.tp3d.get("export_path", None)
    if not exportPath:
        exportPath = addon_preferences.get_prefs().default_export_folder
    if not exportPath:
        _progress.WarningsOverlay.add_warning(_rpt("Export folder not set"), "error")
        return
    bpy.ops.object.select_all(action="DESELECT")
    zobj.select_set(True)
    bpy.context.view_layer.objects.active = zobj

    if zobj.material_slots and force != "STL":
        bpy.ops.wm.obj_export(
            filepath=exportPath + _sanitize_filename(zobj.name) + ".obj",
            export_selected_objects=True,
            export_triangulated_mesh=True,
            apply_modifiers=True,
            export_materials=True,
            forward_axis="Y",
            up_axis="Z",
        )
    else:
        bpy.ops.wm.stl_export(
            filepath=exportPath + _sanitize_filename(zobj.name) + ".stl",
            export_selected_objects=True,
        )

    zobj.select_set(False)  # Select the object


def export_selected_to_STL(force="STL"):
    from .utils import show_message_box

    exportPath = bpy.context.scene.tp3d.get("export_path", None)
    if not exportPath:
        exportPath = addon_preferences.get_prefs().default_export_folder
    if not exportPath:
        _progress.WarningsOverlay.add_warning(_rpt("Export folder not set"), "error")
        return {"FINISHED"}
    selected_objects = bpy.context.selected_objects
    active_obj = bpy.context.active_object

    if not selected_objects:
        show_message_box("No objects selected")
        return {"FINISHED"}

    for zobj in selected_objects:
        bpy.ops.object.select_all(action="DESELECT")
        zobj.select_set(True)
        bpy.context.view_layer.objects.active = zobj

        if (zobj.material_slots or force == "OBJ") and force != "STL":
            bpy.ops.wm.obj_export(
                filepath=exportPath + _sanitize_filename(zobj.name) + ".obj",
                export_selected_objects=True,
                export_triangulated_mesh=True,
                apply_modifiers=True,
                export_materials=True,
                forward_axis="Y",
                up_axis="Z",
            )
            # show_message_box("File Exported as OBJ because it contains Materials","INFO","OBJ File Exported")
        else:
            bpy.ops.wm.stl_export(
                filepath=exportPath + _sanitize_filename(zobj.name) + ".stl",
                export_selected_objects=True,
            )

    bpy.ops.object.select_all(action="DESELECT")
    for zobj in selected_objects:
        zobj.select_set(True)
    bpy.context.view_layer.objects.active = active_obj

    active_obj = bpy.context.active_object


def export_selected_to_3mf(
    filename: str = "", is_auto: bool = False, manual: bool = False
):
    import os
    import tempfile

    from mathutils import Vector

    from .utils import show_message_box

    exportPath = bpy.context.scene.tp3d.get("export_path", "")
    if not exportPath:
        exportPath = addon_preferences.get_prefs().default_export_folder
    if not exportPath:
        _progress.WarningsOverlay.add_warning(_rpt("Export folder not set"), "error")
        return {"FINISHED"}

    selected_objects = bpy.context.selected_objects
    if not selected_objects:
        show_message_box("No objects selected")
        return {"FINISHED"}

    # 1. Duplicate all selected objects + children (preserve hierarchy)
    all_to_export = list(selected_objects)
    for obj in selected_objects:
        for child in obj.children_recursive:
            if child not in all_to_export:
                all_to_export.append(child)

    original_to_dup = {}
    duplicates = []
    scene_col = bpy.context.scene.collection
    for obj in all_to_export:
        dup = obj.copy()
        dup.data = obj.data.copy() if obj.data else None
        scene_col.objects.link(dup)
        original_to_dup[obj] = dup
        duplicates.append(dup)

    # Re-establish parent relationships
    for orig, dup in original_to_dup.items():
        if orig.parent in original_to_dup:
            dup.parent = original_to_dup[orig.parent]
            dup.matrix_parent_inverse = orig.matrix_parent_inverse.copy()
        else:
            dup.parent = None
            dup.matrix_world = orig.matrix_world.copy()

    # Convert curves to mesh
    for obj in duplicates:
        if obj.type == "CURVE":
            bpy.ops.object.select_all(action="DESELECT")
            obj.select_set(True)
            bpy.context.view_layer.objects.active = obj
            bpy.ops.object.convert(target="MESH")

    # With texture-mode paint export, companion objects (text/plate/shell, and
    # the trail when it's excluded from the baked texture) have no paint data
    # of their own -- give each a solid-colour paint texture matching the
    # terrain's own baked palette so the exporter doesn't default them all to
    # extruder 1. Done here (not at generation time) so it's also correct on
    # a plain re-export of an already-generated map, not just a fresh one.
    tp3d = bpy.context.scene.tp3d
    if tp3d.tex_use_texture:
        import ast

        from .props import texture_trail_active
        from .utils.texture import (
            _srgb_to_hex,
            material_to_srgb,
            tag_solid_color_for_paint_export,
        )

        # The palette comes from a *textured* map -- Color by Height mountain
        # pieces are "MAP" objects too (copies of the map) but carry no paint
        # texture, and picking one of those would skip all companions.
        map_dup = next(
            (
                d
                for d in duplicates
                if d.get("Object type") == "MAP"
                and d.type == "MESH"
                and d.data.get("3mf_is_paint_texture")
            ),
            None,
        )
        if map_dup is not None and map_dup.type == "MESH":
            try:
                palette = ast.literal_eval(
                    map_dup.data.get("3mf_paint_extruder_colors", "{}")
                )
            except (ValueError, SyntaxError):
                palette = {}
            if palette:
                # TEXT/PLATE/SHELL are always one fixed colour; TRAIL is not --
                # different trail curves can carry different materials (e.g. a
                # red vs. a yellow trail), so that one must be read from each
                # object's own material rather than assumed to be constant.
                _fixed_companion_material = {
                    "TEXT": "WHITE",
                    "PLATE": "BLACK",
                    "SHELL": "BLACK",
                    "BUILDING": "WHITE",
                }
                _palette_dirty = False
                for dup in duplicates:
                    obj_type = dup.get("Object type")
                    if obj_type in _fixed_companion_material:
                        _ccol = material_to_srgb(
                            bpy.data.materials.get(_fixed_companion_material[obj_type])
                        )
                    elif obj_type == "TRAIL" and not texture_trail_active(tp3d):
                        _own_mat = (
                            dup.data.materials[0]
                            if dup.data and dup.data.materials
                            else None
                        )
                        _ccol = material_to_srgb(
                            _own_mat or bpy.data.materials.get("TRAIL")
                        )
                    elif obj_type == "HOLDER" and not dup.data.get("3mf_is_paint_texture"):
                        _own_mat = (
                            dup.data.materials[0]
                            if dup.data and dup.data.materials
                            else None
                        )
                        _ccol = material_to_srgb(
                            _own_mat or bpy.data.materials.get("BLACK")
                        )
                    elif obj_type in {"BUILDINGS", "ROADS"}:
                        _own_mat = (
                            dup.data.materials[0]
                            if dup.data and dup.data.materials
                            else None
                        )
                        _ccol = material_to_srgb(
                            _own_mat or bpy.data.materials.get(obj_type)
                        )
                    elif (
                        dup.get("IsMountainPiece")
                        and dup.type == "MESH"
                        and not dup.data.get("3mf_is_paint_texture")
                        and dup.data.materials
                        and dup.data.materials[0] is not None
                    ):
                        # Color by Height "Single color" piece: one solid
                        # colour (its HEIGHT_xxxxxx material), which usually
                        # isn't in the terrain's texture palette -- without
                        # this the slicer prints it in extruder 1.
                        _ccol = material_to_srgb(dup.data.materials[0])
                    else:
                        continue
                    _chex = _srgb_to_hex(*_ccol)
                    if _chex not in palette.values():
                        palette[max(palette.keys()) + 1] = _chex
                        _palette_dirty = True
                    tag_solid_color_for_paint_export(dup, _ccol, palette)
                if _palette_dirty:
                    map_dup.data["3mf_paint_extruder_colors"] = str(palette)

    # ------------------------------------------------------------------
    #  New grouping logic based on tp3d.keep_positions
    # ------------------------------------------------------------------
    temp_empties = []  # we'll delete these later
    if bpy.context.scene.tp3d.keep_positions:
        # Group ALL objects under one root, preserve world transforms
        root_empty = bpy.data.objects.new("TP3D_Group", None)
        bpy.context.collection.objects.link(root_empty)
        temp_empties.append(root_empty)

        # Only top‑level objects get parented to the root; children keep their original parent
        top_level = [obj for obj in duplicates if obj.parent is None]
        for obj in top_level:
            world_matrix = obj.matrix_world.copy()
            obj.parent = root_empty
            obj.matrix_parent_inverse = root_empty.matrix_world.inverted()
            obj.matrix_world = world_matrix

        export_roots = [root_empty]  # only one root object to export

    else:
        # Original behaviour: center, group by "ExportGroup" custom property
        center = get_selection_center(duplicates)
        offset = Vector((-center.x, -center.y, -center.z))
        for obj in duplicates:
            obj.location += offset
        place_separate_groups_beside_map(duplicates)

        # Multi Tile Generator objects also carry a MultitileIndex -- each
        # tile (with its own trail/element pieces) is its own group, instead
        # of every tile landing in one shared "Map" group.
        groups = {}
        ungrouped = []
        for obj in duplicates:
            group_id = obj.get("ExportGroup", 0)
            if group_id > 0:
                key = (obj.get("MultitileIndex", -1), group_id)
                groups.setdefault(key, []).append(obj)
            else:
                ungrouped.append(obj)

        GROUP_NAMES = {1: "Map", 2: "Plate"}
        export_roots = []
        for (tile_idx, g_id), members in sorted(groups.items()):
            if len(members) == 1:
                export_roots.append(members[0])
                continue
            name = GROUP_NAMES.get(g_id, f"Group_{g_id}")
            if tile_idx >= 0:
                name = f"{name}_{tile_idx}"
            empty = bpy.data.objects.new(name, None)
            bpy.context.collection.objects.link(empty)
            temp_empties.append(empty)
            export_roots.append(empty)
            for member in members:
                member.parent = empty

        export_roots.extend(ungrouped)

    # ------------------------------------------------------------------
    #  Thumbnail & export (unchanged)
    # ------------------------------------------------------------------
    thumbnail_path = os.path.join(tempfile.gettempdir(), "tp3d_thumbnail.png")
    if not bpy.app.background:
        customThumbnail(duplicates, thumbnail_path)

    base_name = filename if filename else bpy.context.scene.tp3d.modelname
    full_path = exportPath + _sanitize_filename(base_name) + ".3mf"

    _3mf_api = get_threemf_api()
    if _3mf_api is None:
        _progress.WarningsOverlay.add_warning(_rpt("3MF Addon not installed"), "error")
        return

    try:
        tp3d = bpy.context.scene.tp3d
        _is_texture_mode: bool = tp3d.tex_use_texture
        _on_progress = None
        if is_auto:
            _overlay = _progress.ProgressOverlay.get()

            def _on_progress_cb(percent: int, message: str) -> None:
                _overlay.update(0.97 + (percent / 100.0) * 0.03, "3MF Export", message)

            _on_progress = _on_progress_cb

        export_kwargs = {
            "filepath": full_path,
            "objects": export_roots,
            "use_mesh_modifiers": True,
            "global_scale": 0.001,
            "coordinate_precision": 4,
            "thumbnail_mode": "NONE" if bpy.app.background else "CUSTOM",
            "thumbnail_image": thumbnail_path if not bpy.app.background else "",
            "thumbnail_resolution": 256,
            "use_orca_format": "PAINT" if _is_texture_mode else "AUTO",
            "progress_mode": "NONE" if is_auto else "AUTO",
            "on_progress": _on_progress,
        }
        if has_threemf_capability("slicer_profile"):
            export_kwargs["slicer_profile"] = tp3d.slicer_profile_name
        else:
            _progress.WarningsOverlay.add_warning(
                _rpt("3MF Addon update available"), "warn"
            )

        result = _3mf_api.export_3mf(**export_kwargs)
        if result.status != "FINISHED":
            print("Export Error:\n" + "\n".join(result.warnings))
            raise Exception(_("3MF export failed"))  # noqa: TRY002
        if not manual:
            _progress.WarningsOverlay.add_warning(_rpt("Exported as 3mf"), "ok")
    except Exception as e:
        print(f"Export Error: {e}")
        _progress.WarningsOverlay.add_warning(_rpt("Exporting as 3mf Failed"), "error")

    # 5. Cleanup (delete duplicates and temporary empties)
    for obj in duplicates + temp_empties:
        if obj is None:
            continue
        for col in obj.users_collection:
            col.objects.unlink(obj)
        bpy.data.objects.remove(obj)

    return {"FINISHED"}


def customThumbnail(objects, output_path, resolution=256):
    scene = bpy.context.scene

    # 1. Setup Render Resolution
    orig_x = scene.render.resolution_x
    orig_y = scene.render.resolution_y
    scene.render.resolution_x = resolution
    scene.render.resolution_y = resolution
    scene.render.resolution_percentage = 100

    # 2. Find 3D View (Crucial for saving state)
    area = next((a for a in bpy.context.screen.areas if a.type == "VIEW_3D"), None)
    if not area:
        return  # Safety exit

    space = area.spaces.active
    rv3d = space.region_3d

    # 3. SAVE INITIAL STATE (Pixel-perfect)
    old_camera = scene.camera
    old_shading = space.shading.type
    old_overlay = space.overlay.show_overlays
    old_view_matrix = rv3d.view_matrix.copy()  # Saves rotation/zoom
    old_perspective = rv3d.view_perspective

    # 4. Setup Temporary Camera
    tmp_cam_data = bpy.data.cameras.new("TempTopCam")
    tmp_cam_data.type = "ORTHO"
    tmp_cam_obj = bpy.data.objects.new("TempTopCam", tmp_cam_data)
    scene.collection.objects.link(tmp_cam_obj)

    # Position: High up, looking straight down
    tmp_cam_obj.location = (0, 0, 100)
    tmp_cam_obj.rotation_euler = (0, 0, 0)
    scene.camera = tmp_cam_obj

    # 5. Set Viewport for Render
    space.shading.type = "MATERIAL"
    space.overlay.show_overlays = False

    # 6. Selection & Framing
    bpy.ops.object.select_all(action="DESELECT")
    for obj in objects:
        obj.select_set(True)

    # 7. Execute Render with Override
    with bpy.context.temp_override(area=area, region=area.regions[-1]):
        # Snap view to the temp camera
        rv3d.view_perspective = "CAMERA"

        # Zoom camera to fit objects
        bpy.ops.view3d.camera_to_view_selected()

        # Render the viewport
        scene.render.filepath = output_path
        bpy.ops.render.opengl(write_still=True, view_context=True)

    # 8. RESTORE INITIAL STATE
    scene.camera = old_camera
    space.shading.type = old_shading
    space.overlay.show_overlays = old_overlay

    # Use the saved matrix to teleport the view back
    rv3d.view_matrix = old_view_matrix
    rv3d.view_perspective = old_perspective

    # Update resolution
    scene.render.resolution_x = orig_x
    scene.render.resolution_y = orig_y

    # Cleanup camera data
    bpy.data.objects.remove(tmp_cam_obj, do_unlink=True)
    bpy.data.cameras.remove(tmp_cam_data, do_unlink=True)


def save_history_thumbnail(history_id, objects):
    """Render *objects* top-down via customThumbnail() and save it as
    <history_id>.png under constants.generation_history_thumbnails_dir, for
    the picker pages' generation-history panel (assets/history_panel.js,
    served via picker_server.py's /get_history_render) to pick up the next
    time that page's picker reopens.

    Called from each generator operator's own "generation succeeded" point
    right after Send -- by then the picker session that recorded this
    history entry has already POSTed its settings/vector-sketch thumbnail
    and (almost always) closed its browser window and shut down its own
    HTTP server, so there is no live page left to push the real render to
    directly. Independent of the 3MF export flow entirely (no dependency on
    auto-export being on or the 3MF addon being installed) -- this is the
    same customThumbnail() the 3MF export thumbnail uses, just called here
    on its own.

    No-ops quietly with a falsy *history_id* (the sending page failed to
    reach /save_history_entry, or is an older cached page from before this
    existed), no *objects*, or in headless mode (customThumbnail needs a
    live 3D viewport, same limitation the 3MF thumbnail already has).
    """
    if not history_id or not objects or bpy.app.background:
        return
    import pathlib

    from . import constants as const

    thumb_dir = pathlib.Path(const.generation_history_thumbnails_dir)
    try:
        thumb_dir.mkdir(parents=True, exist_ok=True)
        customThumbnail(list(objects), str(thumb_dir / f"{history_id}.png"))
    except (OSError, RuntimeError, AttributeError) as e:
        print(f"[TP3D] Failed to save history thumbnail for {history_id}: {e}")


def get_selection_center(objects):
    if not objects:
        return Vector((0, 0, 0))

    all_coords = []

    for obj in objects:
        # Get all 8 corners of the bounding box in World Space
        # matrix_world @ corner converts local box to world position
        bbox_corners = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]
        all_coords.extend(bbox_corners)

    # Find the min and max for each axis across ALL objects
    min_x = min(c.x for c in all_coords)
    max_x = max(c.x for c in all_coords)

    min_y = min(c.y for c in all_coords)
    max_y = max(c.y for c in all_coords)

    min_z = min(c.z for c in all_coords)

    center = Vector(
        (
            (min_x + max_x) / 2,
            (min_y + max_y) / 2,
            min_z,
        )
    )

    return center


def _x_extent(objects):
    xs = [
        (obj.matrix_world @ Vector(corner)).x
        for obj in objects
        for corner in obj.bound_box
    ]
    return min(xs), max(xs)


def place_separate_groups_beside_map(objects, gap=10.0):
    """Move the objects printed apart from the map -- ExportGroup 0 (e.g. a
    Single Extruder trail or element) and 2 (plate) -- beside it along +X,
    each group as one block, *gap* mm apart. They'd otherwise sit at their
    real position inside/under the map, where the slicer hides them."""
    bpy.context.view_layer.update()
    map_objs = [o for o in objects if o.get("ExportGroup") == 1]
    if not map_objs:
        return
    _min_x, cursor = _x_extent(map_objs)
    for group_id in (0, 2):
        members = [o for o in objects if o.get("ExportGroup") == group_id]
        if not members:
            continue
        g_min, g_max = _x_extent(members)
        dx = cursor + gap - g_min
        # Children follow their parent; moving them too would double-shift.
        for obj in members:
            if obj.parent is None:
                obj.location.x += dx
        cursor = g_max + dx


def is_3mf_extension_installed():
    is_en = is_threemf_available()
    temp.has3mf = is_en
    return is_en
